// ─── IEvaluationService.ts ───────────────────────────────────────────────────
// Evaluation tab-க்கு தேவையான எல்லா API contracts

import { InterviewPanaldata } from "../../Models/Screens";

// ── Types ────────────────────────────────────────────────────────────────────

export type EvaluationCandidate = {
  id: number;
  applicantName: string;
  positionTitle: string;
  interviewDate: string;
  interviewLevel: string;
  grade: string;
  gradeLabel: string;
  attachments: number;
  status: string;
  statusId: number | string;
  recruitmentID: number | string;
  jobCodeID: number;
  interviewDateTime: string;
};

export type TooltipEntry = {
  Key: string;   // person name
  Value: string; // "Completed" | "Pending"
};

export type ScoreSheetResult =
  | { canProceed: true }
  | { canProceed: false; level: string };

// ── Interface ────────────────────────────────────────────────────────────────

export interface IEvaluationService {
  getCurrentUserGuid(email: string): Promise<string | null>;
  getInterviewPanelsByUser(userGuid: string): Promise<InterviewPanaldata[]>;
  getCombinedCandidates(candidateIDs: number[], employeeList: any[]): Promise<any[]>;
  getGradeAndLevel(recruitmentID: number): Promise<{ grade: string; level: string; jobCodeID: number }>;
  getTooltipData(candidateID: number, interviewLevel: string): Promise<TooltipEntry[]>;
  checkScoreSheet(candidateID: number, statusId: number | string, userEmail: string): Promise<ScoreSheetResult>;
}
